def clean(v: Any) -> str:
    s = "" if v is None else str(v).strip()
    if s.lower() in {"nan", "none", "nat", "null", "<na>", "--", "---", "----"}:
        return ""
    return s

def parse_date(v: Any) -> Optional[str]:
    s = clean(v).replace("\ufeff", "").split(" ")[0]
    if not s:
        return None
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    if re.fullmatch(r"\d{8}", s):
        try:
            return datetime.strptime(s, "%Y%m%d").date().isoformat()
        except ValueError:

def norm_market(v: Any) -> str:
    s = clean(v).upper().replace(" ", "")
    if s in {"TWSE", "上市", "證交所", "TSE", "TW"} or "上市" in s or "TWSE" in s:
        return "TWSE"
    if s in {"TPEX", "上櫃", "櫃買", "OTC", "TP"} or "上櫃" in s or "櫃買" in s or "TPEX" in s:
        return "TPEX"
    return s

def norm_code(v: Any) -> str:
    s = clean(v).replace(" ", "")
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    return s.upper()

def num(v: Any) -> float:
    s = clean(v).replace(",", "")
    if not s:
        return float("nan")
    try:
        x = float(s)
        return x if math.isfinite(x) else float("nan")
    except Exception:
        return float("nan")

def fmt_num(v: float) -> str:
    if not math.isfinite(float(v)):
        return ""
    return format(float(v), ".17g")

def find_col(cols: Sequence[str], aliases: Sequence[str]) -> Optional[str]:
    cmap = {norm(c): str(c) for c in cols}
    for a in aliases:
        if norm(a) in cmap:
            return cmap[norm(a)]
    for a in aliases:
        na = norm(a)
        hits = [str(c) for c in cols if na and na in norm(c)]
        if len(hits) == 1:
            return hits[0]

