def sort_key_from_row(row: Sequence[str], idx: Dict[str, int], mode: str) -> Tuple[str, ...]:
    d = parse_date(row[idx["date"]])
    m = norm_market(row[idx["market"]])
    c = norm_code(row[idx["code"]])
    s = clean(row[idx["segment"]])
    if not d or not m or not c or not s:
        raise ValueError(f"排序資料自然鍵缺值／日期錯誤：date={d}, market={m}, code={c}, segment={s}")
    if mode == "group":
        return (m, c, s, d)
    return (d, m, c, s)

