def write_gzip_csv_progress(df: pd.DataFrame, path: Path, label: str, chunk: int = 100_000) -> None:
    started = time.monotonic()
    with gzip.open(path, "wt", encoding="utf-8-sig", newline="") as f:
        for start in range(0, len(df), chunk):
            end = min(len(df), start + chunk)
            df.iloc[start:end].to_csv(f, index=False, header=(start == 0), lineterminator="\n")
            log(f"{label} {bar(end/max(1,len(df))*100)} | 已寫 {end:,}/{len(df):,} 列 | {elapsed(time.monotonic()-started)}")

