def sha256_file(path: Path, block_size: int = 8 * 1024 * 1024) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        while True:
            block = f.read(block_size)
            if not block:
                break
            h.update(block)
    return h.hexdigest()

def verify_embedded_sources() -> None:
    actual = {
        "v4.69": hashlib.sha256(V469_SOURCE.encode("utf-8")).hexdigest(),
        "v4.70.1": hashlib.sha256(V4701_SOURCE.encode("utf-8")).hexdigest(),
    }
    expected = {"v4.69": V469_SOURCE_SHA256, "v4.70.1": V4701_SOURCE_SHA256}
    for name in expected:
        log(f"原始程式 SHA256 {name}: {actual[name]}")
        if actual[name] != expected[name]:
            raise RuntimeError(f"內嵌原始程式雜湊不符：{name}；停止執行")

