def newest_dir(root: Path, pattern: str) -> Path:
    found = [p for p in root.glob(pattern) if p.is_dir()]
    if not found:
        raise FileNotFoundError(f"找不到來源資料夾：{pattern}")
    return max(found, key=lambda p: p.stat().st_mtime)

def stream_subprocess(command: Sequence[str], label: str) -> None:
    log(f"開始執行 {label}。")
    log("命令列：" + " ".join(str(x) for x in command[:5]) + (" ..." if len(command) > 5 else ""))
    proc = subprocess.Popen(
        list(command), stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
        text=True, encoding="utf-8", errors="replace", bufsize=1
    )
    assert proc.stdout is not None
    for line in proc.stdout:
        print(line.rstrip("\n"), flush=True)

