def v251_pick_col(cols: Sequence[str], aliases: Sequence[str], contains_any: Optional[Sequence[str]] = None) -> Optional[str]:
    """Same column-selection precedence as SSO v2.51 infer_schema()/pick_col()."""
    cols = list(cols)
    for item in aliases:
        if item in cols:
            return item
    lookup = {str(c).lower(): c for c in cols}
    for item in aliases:
        if item.lower() in lookup:
            return lookup[item.lower()]

def v251_numeric_text(value: Any) -> str:
    if value is None or pd.isna(value):
        return ""
    try:
        number = float(value)
        if not np.isfinite(number):
            return ""
    except Exception:
        return str(value)
    # Preserve float32's shortest round-trippable decimal representation, as in the v2.51 frame.

