def resolve_wrapper_source() -> Tuple[str, Optional[Path], str]:
    """取得目前主程式完整原始碼，兼容 .py、Colab 儲存格與 IPython 暫存執行。"""
    expected_marker = 'VERSION = "v4.84.9.8"'
    required_markers = (expected_marker, "V469_SOURCE = r", "def main() -> None:")

    def valid_source(source: str) -> bool:
        return all(marker in source for marker in required_markers)

    # 1. 以 python file.py 或 !python file.py 執行時，使用真正的 __file__。
    raw_file = globals().get("__file__")
